def table(self, table: Any) -> None:
    grid = max(1, len(table._tbl.tblGrid.gridCol_lst))
    rows: list[list[str]] = []
    for tr in table._tbl.tr_lst:
        if rows and self._builder.out_of_time():
            break
        cells: list[str] = []
        for tc in tr.tc_lst:
            if len(cells) >= grid:
                break
            text = self._docx.table._Cell(tc, table).text
            cells.extend([text] * max(1, min(tc.grid_span, grid - len(cells))))
        rows.append(cells)
    self._builder.table(rows)
